157	    pub fn append_loss_governor_manual_recovery(
158	        &self,
159	        manual_recovery: KillSwitchLossGovernorManualRecoveryRecord,
160	    ) -> Result<usize, KillSwitchStoreError> {
161	        let previous_count = self.loss_governor_manual_recovery_audit_appendable_line_count()?;
162	        let mut bytes =
163	            serde_json::to_vec(&manual_recovery).map_err(KillSwitchStoreError::Serialize)?;
164	        bytes.push(b'\n');
165	        append_private_file(&self.loss_governor_manual_recovery_audit_path(), &bytes)?;
166	        Ok(previous_count.saturating_add(1))
167	    }
