236	                source,
237	            })?;
238	        let mut last_byte = [0_u8; 1];
239	        file.read_exact(&mut last_byte)
240	            .map_err(|source| KillSwitchStoreError::Io {
241	                path: audit_path.clone(),
242	                source,
243	            })?;
244	        if last_byte[0] != b'\n' {
245	            log::error!(
246	                "refusing to append loss-governor manual recovery audit line because {} does not end with a newline",
247	                audit_path.display()
248	            );
249	            return Err(KillSwitchStoreError::TornManualRecoveryAudit { path: audit_path });
250	        }
251	        file.seek(SeekFrom::Start(0))
252	            .map_err(|source| KillSwitchStoreError::Io {
253	                path: audit_path.clone(),
254	                source,
255	            })?;
256	        let reader = io::BufReader::new(file);
257	        let mut count = 0;
258	        for line in reader.lines() {
259	            let line = line.map_err(|source| KillSwitchStoreError::Io {
260	                path: audit_path.clone(),
261	                source,
262	            })?;
263	            if !line.trim().is_empty() {
264	                count += 1;
265	            }
266	        }
267	        Ok(count)
268	    }
