270	    pub fn bootstrap_initial_armed_loss_snapshot(&self) -> Result<(), KillSwitchStoreError> {
271	        let snapshot = initial_armed_loss_protection_snapshot();
272	        let bytes = serialize_state_with_loss_snapshot(&KillSwitchState::Armed, Some(&snapshot))?;
273	        self.ensure_state_bytes_within_limit(&bytes)?;
274	        match write_private_new_file(&self.path, &bytes) {
275	            Ok(()) => Ok(()),
276	            Err(error) => {
277	                if error.source.kind() == io::ErrorKind::AlreadyExists && error.path == self.path {
278	                    Err(KillSwitchStoreError::StateAlreadyExists { path: error.path })
279	                } else {
280	                    Err(KillSwitchStoreError::from(error))
281	                }
282	            }
283	        }
284	    }
