149	fn private_atomic_temp_path_for_write(path: &Path) -> PathBuf {
150	    let counter = PRIVATE_ATOMIC_TEMP_COUNTER.fetch_add(1, Ordering::Relaxed);
151	    let timestamp_ns = SystemTime::now()
152	        .duration_since(UNIX_EPOCH)
153	        .map(|duration| duration.as_nanos())
154	        .unwrap_or(0);
155	    private_atomic_temp_path_with_suffix(
156	        path,
157	        &format!("tmp.{}.{}.{}", std::process::id(), timestamp_ns, counter),
158	    )
159	}
