161	fn private_atomic_temp_path_with_suffix(path: &Path, suffix: &str) -> PathBuf {
162	    let mut temp_path = path.as_os_str().to_os_string();
163	    temp_path.push(".");
164	    temp_path.push(suffix);
165	    PathBuf::from(temp_path)
166	}
