190	#[cfg(unix)]
191	fn configure_file_options(options: &mut OpenOptions, mode: u32) {
192	    use std::os::unix::fs::OpenOptionsExt;
193	    // Bound the create-time mode so the brief pre-chmod window is never *more* permissive
194	    // than requested; `enforce_exact_file_mode` then pins the exact mode regardless of umask.
195	    options.mode(mode);
196	}
