201	#[cfg(unix)]
202	fn enforce_exact_file_mode(file: &fs::File, path: &Path, mode: u32) -> Result<(), AtomicIoError> {
203	    use std::os::unix::fs::PermissionsExt;
204	    file.set_permissions(fs::Permissions::from_mode(mode))
205	        .map_err(|source| AtomicIoError {
206	            path: path.to_path_buf(),
207	            source,
208	        })
209	}
